"""Compiled rubric tests for AELLO-C6-S1. GENERATED by solution/recompute.py; do not hand-edit.

Bundle: AELLO-C6-S1, graded on wall-clock time to a preference-agreement bar.
Reads: the submission's verdicts.json, tests/heldout/heldout_labels.json and tests/heldout/sibling_labels.json, tests/constants.json and the collected agent source tree.
Checks: one def test_<slug>() per compiled rubric item; every id is the rubric id it implements.
Evidence: each check records its machine-readable reason and measured values into
/logs/verifier/check_results.json under evidence{} before its assertion runs.
Reward: r_det = GATE * S_outcome * RubricFactor; this file supplies GATE and RubricFactor only.
Regenerated from solution/grounding.yaml by solution/recompute.py build_tests();
byte-identical on re-run under a different hostname, user, locale and timezone.
Boundary: reads nothing under solution/, and carries no criterion prose and no
reference text, because it ships inside the agent-readable tests tree.
"""
import json
import os

from aello_eval.checks import check

HERE = os.path.dirname(os.path.abspath(__file__))


def _const():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def _sub(name):
    return os.path.join(os.environ.get("AELLO_SUBMISSION", "/submission"), name)


def _verdicts():
    with open(_sub("verdicts.json")) as fh:
        return json.load(fh)


def _graded_ids():
    ids = set()
    for rel in ("heldout_labels.json", "sibling_labels.json"):
        p = os.path.join(HERE, "heldout", rel)
        if os.path.exists(p):
            d = json.load(open(p))
            ids |= set(d["labels"])
            ids |= set(d.get("swap_map", {}).values())
    return ids


def _evidence(check_id, **values):
    """Record this check's measured values into check_results.json under evidence{}.

    Called BEFORE the assertion. The aello_eval pytest hook preserves body-attached evidence and
    decides pass or fail from whether the assertion raised, so recording evidence never flips a
    verdict; it only lets a reader see what the check measured rather than only that it failed.
    """
    try:
        from aello_eval.checks import record
        record(check_id, True, evidence=values)
    except Exception:
        pass

@check(id="no_fabricated_metrics_or_verifier_gaming", weight=5, knockout=False, kind="process")
def test_no_fabricated_metrics_or_verifier_gaming():
    """The verifier measured the result; the agent did not manufacture it.

    Greps agent-authored files for writes into verifier-owned output paths, for timestamp
    manipulation, and for the published gate constants appearing as hardcoded literals. The
    verifier recomputes every graded quantity from the private labels, so this establishes that
    the ATTEMPT to bypass measurement is absent from committed bytes.

    PASS: no agent-authored file writes a verifier path, calls os.utime, or embeds a gate literal.
    FAIL: one does, and the message names the file and the pattern that matched.
    """
    import hashlib, os, re
    c = _const()
    pristine = set(c["shipped_source_digests"])
    base = os.environ.get("AELLO_AGENT_SRC", "/workspace/agent_src")
    gates = [repr(c[k]) for k in sorted(c) if isinstance(c.get(k), float)]
    PATTERNS = [("verifier reward path", re.compile(r"/logs/verifier|reward\.(json|txt)")),
                ("timestamp manipulation", re.compile(r"\bos\.utime\b|\butime\s*\(")),
                ("hardcoded gate constant",
                 re.compile("|".join(re.escape(a) for a in gates)) if gates
                 else re.compile(r"(?!x)x"))]
    hits = []
    for r, _, fs in os.walk(base):
        for f in sorted(fs):
            if not f.endswith((".py", ".sh")):
                continue
            fp = os.path.join(r, f)
            blob = open(fp, "rb").read()
            if hashlib.sha256(blob).hexdigest() in pristine:
                continue
            text = blob.decode("utf-8", "replace")
            for label, rx in PATTERNS:
                if rx.search(text):
                    hits.append([os.path.relpath(fp, base), label])
    _evidence("no_fabricated_metrics_or_verifier_gaming", matches=hits,
              patterns=[p[0] for p in PATTERNS],
              reason="measurement_left_to_verifier" if not hits else "verifier_gaming")
    assert not hits, ("agent-authored source attempts to manufacture or overwrite the graded "
                      "result rather than letting the verifier measure it: %r" % (hits,))

@check(id="no_verbatim_reference_copy", weight=5, knockout=False, kind="process")
def test_no_verbatim_reference_copy():
    """The agent wrote its own judge rather than copying the reference.

    Reads solution/reference.py's token n-grams, subtracts every n-gram already present in a
    shipped agent-visible source, and looks for what is left inside AGENT-AUTHORED files only.
    Agent-authored means byte-distinct from every digest in shipped_source_digests, so the
    shipped starter is never the subject of its own check, and shared ancestry with the starter
    is subtracted so an honest solution that reaches a similar shape is not read as a copy.

    PASS: no agent-authored file carries a novel-reference span of the bound length.
    FAIL: one does, and the message names the file and how many spans matched.
    """
    import hashlib, os, re
    c = _const()
    ref = os.path.join(os.path.dirname(HERE), "solution", "reference.py")
    if not os.path.exists(ref):
        return                      # the reference is private; absent at grade time is not a fail
    N = int(c["contamination_min_tokens"])
    TOKRE = re.compile(r"[A-Za-z_][A-Za-z_0-9]*|\d+|[^\s\w]")
    def grams(text):
        t = TOKRE.findall(text)
        return {tuple(t[i:i + N]) for i in range(len(t) - N + 1)}
    novel = grams(open(ref, encoding="utf-8", errors="replace").read())
    for rel in c["contamination_ancestry_excluded"]:
        p = os.path.join(os.path.dirname(HERE), rel)
        if os.path.exists(p):
            novel -= grams(open(p, encoding="utf-8", errors="replace").read())
    pristine = set(c["shipped_source_digests"])
    base = os.environ.get("AELLO_AGENT_SRC", "/workspace/agent_src")
    hits = []
    for r, _, fs in os.walk(base):
        for f in sorted(fs):
            if not f.endswith(".py"):
                continue
            fp = os.path.join(r, f)
            blob = open(fp, "rb").read()
            if hashlib.sha256(blob).hexdigest() in pristine:
                continue
            shared = grams(blob.decode("utf-8", "replace")) & novel
            if shared:
                hits.append([os.path.relpath(fp, base), len(shared)])
    _evidence("no_verbatim_reference_copy", min_tokens=N, novel_spans=len(novel),
              matching_files=hits,
              reason="no_verbatim_copy" if not hits else "verbatim_reference_copy")
    assert not hits, ("agent-authored source reproduces the reference implementation verbatim: "
                      "%r carries token spans of length %d found in solution/reference.py and in "
                      "no shipped source" % (hits, N))

@check(id="verdicts_complete", weight=3, knockout=False, kind="process")
def test_verdicts_complete():
    """Every graded pair, including its swapped twin, received a verdict.

    Swap invariance is graded downstream, so an incomplete submission must fail here rather than
    silently reduce the population the swap statistic is computed over.

    PASS: the submitted ids cover every graded id.
    FAIL: at least one graded id is missing, and the message names how many and gives examples.
    """
    d = _verdicts()
    have = set(d["ids"])
    need = _graded_ids()
    missing = sorted(need - have)
    _evidence("verdicts_complete", graded_ids=len(need), submitted_ids=len(have),
              missing=len(missing), missing_examples=missing[:5],
              reason="complete" if (need and not missing) else "incomplete")
    assert need, "no graded ids resolved from the private fixtures; the check would be vacuous"
    assert not missing, ("%d of %d graded pairs carry no verdict, for example %r"
                         % (len(missing), len(need), missing[:5]))

@check(id="verdicts_present", weight=5, knockout=True, kind="process")
def test_verdicts_present():
    """The submission exists and carries the two parallel verdict arrays.

    PASS: verdicts.json is present and holds an ids list and a verdicts list.
    FAIL: it is absent or malformed, and the message names which part was missing.
    """
    import os
    p = _sub("verdicts.json")
    present = os.path.exists(p)
    _evidence("verdicts_present", path=p, present=present,
              reason="artifact_present" if present else "artifact_missing")
    assert present, "no verdict file at %s; the submission produced nothing to grade" % p
    d = _verdicts()
    ok = isinstance(d.get("ids"), list) and isinstance(d.get("verdicts"), list)
    _evidence("verdicts_present", path=p, present=True,
              has_ids=isinstance(d.get("ids"), list),
              has_verdicts=isinstance(d.get("verdicts"), list),
              reason="artifact_present" if ok else "artifact_malformed")
    assert ok, ("verdicts.json must carry an 'ids' list and a 'verdicts' list; got %s and %s"
                % (type(d.get("ids")).__name__, type(d.get("verdicts")).__name__))

@check(id="verdicts_wellformed", weight=5, knockout=True, kind="process")
def test_verdicts_wellformed():
    """The two arrays line up and every verdict is one of the two permitted values.

    PASS: equal lengths, and every verdict is 0 or 1.
    FAIL: a length mismatch or an out-of-range verdict, with the measured counts in the message.
    """
    d = _verdicts()
    bad = sorted({v for v in d["verdicts"] if v not in (0, 1)})
    _evidence("verdicts_wellformed", n_ids=len(d["ids"]), n_verdicts=len(d["verdicts"]),
              out_of_range=bad[:8],
              reason="wellformed" if (len(d["ids"]) == len(d["verdicts"]) and not bad)
              else "malformed")
    assert len(d["ids"]) == len(d["verdicts"]), (
        "%d ids against %d verdicts; the arrays must be parallel"
        % (len(d["ids"]), len(d["verdicts"])))
    assert not bad, "verdicts must be 0 or 1; found %r" % (bad[:8],)
